    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort(key=lambda x: x[0])

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, update the end of the last merged interval
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
